questions.modelAnswer:
class Trie {
    struct Node {
        array<unique_ptr<Node>, 26> ch;
        bool end = false;
    };
    Node root;

    const Node* walk(const string& s) const {
        const Node* cur = &root;
        for (char c : s) {
            cur = cur->ch[c - 'a'].get();
            if (!cur) return nullptr;
        }
        return cur;
    }
public:
    void insert(const string& w) {
        Node* cur = &root;
        for (char c : w) {
            auto& next = cur->ch[c - 'a'];
            if (!next) next = make_unique<Node>();
            cur = next.get();
        }
        cur->end = true;
    }
    bool search(const string& w) const {
        const Node* n = walk(w);
        return n && n->end;
    }
    bool startsWith(const string& p) const { return walk(p) != nullptr; }
};

