    Node* cur = root;
    int res = 0;
    for (int i = 0; i <= 30; ++i) {
        int b = (x >> i) & 1;
        if (cur->ch[b ^ 1]) {
            res |= 1 << i;
            cur = cur->ch[b ^ 1];
        } else {
            cur = cur->ch[b];
        }
    }
    return res;
